  "evidence": [
   {
    "quote": "Disallow setting custom options that match the name of an installed extension, but are not one of the extension's declared variables",
    "source": "PostgreSQL 15 release notes: Migration to Version 15",
    "release_of_change": "15"
   }
  ]
 },
 {
  "condition_id": "such_pre_existing_variables_were_set_bef_401659",
  "claim": "Such pre-existing variables were set before the extension is loaded in the session (they will be deleted at extension load).",
  "evidence": [
   {
    "quote": "This change causes any such pre-existing variables to be deleted during extension load",
    "source": "PostgreSQL 15 release notes: Migration to Version 15",
    "release_of_change": "15"
   }
  ]
 }
]
